1	package netdiag
2	
3	import (
4		"context"
5		"log"
6		"net/netip"
7		"time"
8	
9		"github.com/anthnel/devdesk/internal/docker"
10		"github.com/anthnel/devdesk/internal/netiface"
11	)
12	
13	// readPathBridge reads the host interface that carries the gateway of the
14	// container's default-route network: the engine gives the interface name, this
15	// machine's interfaces say whether it exists. It returns "" when there is
16	// nothing to find or a read failed (logged, never shown, unless the run was
17	// canceled). The result is display-safe.
18	func readPathBridge(ctx context.Context, n docker.ContainerNetworking, timeout time.Duration, e pathEngine) string {
19		if !n.Running {
20			return ""
21		}
22		ep, ok := routeEndpoint(n)
23		if !ok || ep.NetworkID == "" {
24			return ""
25		}
26		nctx, cancel := context.WithTimeout(ctx, timeout)
27		defer cancel()
28		nb, err := e.network(nctx, ep.NetworkID)
29		if err != nil {
30			logBridgeError(ctx, "network", err)
31			return ""
32		}
33		if nb.Name == "" {
34			return ""
35		}
36		ifaces, err := e.interfaces(nctx)
37		if err != nil {
38			logBridgeError(ctx, "interfaces", err)
39			return ""
40		}
41		return engineText(hostBridge(nb.Name, ep.Gateway, ifaces))
42	}
43	
44	// logBridgeError logs a read failure unless the run was canceled.
45	func logBridgeError(ctx context.Context, what string, err error) {
46		if ctx.Err() == nil {
47			log.Printf("ERROR [netdiag/path] bridge %s: %v", what, err)
48		}
49	}
50	
51	// hostBridge returns the name of this machine's interface called exactly want
52	// (case sensitive) that carries gw among its IPv4 addresses, or "" when there
53	// is none. Malformed CIDR entries are ignored.
54	func hostBridge(want string, gw netip.Addr, ifaces []netiface.Interface) string {
55		if want == "" || !gw.IsValid() {
56			return ""
57		}
58		for _, ifc := range ifaces {
59			if ifc.Name != want {
60				continue
61			}
62			for _, cidr := range ifc.IPv4 {
63				if p, err := netip.ParsePrefix(cidr); err == nil && p.Addr() == gw {
64					return ifc.Name
65				}
66			}
67		}
68		return ""
69	}
